// The monitoring page. Everything it knows comes from three places: HTTP
// checks it makes itself, the host snapshot written by the vitals script, and
// GitHub's view of the last deploy.
//
// Every rule that decides a colour is written down here rather than implied,
// because a dashboard whose thresholds nobody can find is one nobody trusts.

const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');

const safe = (name, path, fallback) => {
  try {
    let v = $(name).first().json;
    for (const k of path) v = v?.[k];
    return v === undefined || v === null ? fallback : v;
  } catch (e) { return fallback; }
};

// --- what we asked, and what came back -------------------------------------
// Every check reports one of three things, and says which.
//
//   green — it answered. 401 and 403 count: an API that refuses an
//           unauthenticated request is working exactly as it should.
//   red   — it answered badly, or did not answer at all. A refused
//           connection or a DNS failure is a down signal, not a mystery.
//   grey  — the check itself did not run. That is not "fine" and it is not
//           "down"; it means this page is blind in one eye, and it is
//           listed as a fault rather than quietly left out.
const check = (name) => {
  let j;
  try { j = $(name).first().json; } catch (e) { j = null; }
  if (!j) return { state: 'grey', note: 'the check did not run' };
  const code = j.statusCode;
  if (typeof code !== 'number') {
    // The node continued past a failure, so there is a message but no reply.
    return j.error !== undefined
      ? { state: 'red', note: 'no answer' }
      : { state: 'grey', note: 'the check did not run' };
  }
  return code > 0 && code < 500
    ? { state: 'green', note: null }
    : { state: 'red', note: 'HTTP ' + code };
};

const v = safe('Host vitals', [], {}) || {};
const hasVitals = Boolean(v.generated);
const ageMin = hasVitals
  ? Math.round((Date.now() - new Date(v.generated).getTime()) / 60000) : null;

// --- the rules -------------------------------------------------------------
// RED means do something now. AMBER means do something this week.
const worst = (...states) =>
  states.includes('red') ? 'red' : states.includes('amber') ? 'amber' : 'green';

const band = (value, amberAt, redAt) =>
  value >= redAt ? 'red' : value >= amberAt ? 'amber' : 'green';
const bandDown = (value, amberAt, redAt) =>
  value <= redAt ? 'red' : value <= amberAt ? 'amber' : 'green';

const disks = (v.disks || []).map(d => ({ ...d, state: band(d.pct, 80, 90) }));
const mem = v.memory || {};
const memState = hasVitals ? bandDown(mem.availableMb || 0, 400, 150) : 'grey';
const swap = v.swap || {};
const swapPct = swap.totalMb ? Math.round((swap.usedMb / swap.totalMb) * 100) : 0;
const swapState = !swap.totalMb ? 'amber' : band(swapPct, 40, 75);

const certs = (v.certificates || []).map(c => ({ ...c, state: bandDown(c.days, 21, 7) }));
// A backup that has never run and one that ran three days ago are the same
// problem: there is no recent copy of the business.
const backups = (v.backups || []).map(b => ({
  ...b,
  state: b.ageHours < 0 || b.ageHours > 72 ? 'red' : b.ageHours > 36 ? 'amber' : 'green',
}));
const containers = (v.containers || []).map(c => ({
  ...c, state: c.state === 'running' ? 'green' : 'red',
}));

// Things that are not containers: nginx, docker, webmin, the renewal timer.
// "unknown" means systemd has never heard of the unit — installed-and-stopped
// and never-installed are different problems and should not share a colour.
const units = (v.services || []).map(u => ({
  name: u.name,
  word: u.state === 'unknown' || u.state === 'not-found' ? 'not installed' : u.state,
  state: u.state === 'active' ? 'green'
       : u.state === 'activating' || u.state === 'reloading' ? 'amber'
       : u.state === 'unknown' || u.state === 'not-found' ? 'grey'
       : 'red',
}));

const upd = v.updates || {};
const updState = !hasVitals ? 'grey'
  : upd.rebootRequired || upd.security > 0 ? 'amber'
  : upd.pending > 25 ? 'amber' : 'green';

// A snapshot that has stopped being written is itself a fault — and a
// dangerous one, because every number on this page would still look fine.
// The snapshot is rewritten every minute, so these are deliberately tight.
// Set against the old five-minute timer they were generous enough that a
// stopped timer could go a quarter of an hour unremarked.
const vitalsState = !hasVitals ? 'red' : ageMin > 15 ? 'red' : ageMin > 5 ? 'amber' : 'green';

const services = [
  { name: 'Website',        key: 'Website up?',      where: 'itsurgery.me' },
  { name: 'Dashboard host', key: null,               where: 'you are reading it' },
  { name: 'CRM',            key: 'CRM up?',          where: 'crm.itsurgery.me' },
  { name: 'Remote help',    key: 'Remote help up?',  where: 'help.itsurgery.me' },
  { name: 'Bookings',       key: 'Cal.com up?',      where: 'cal.com' },
  { name: 'Payments',       key: 'Stripe up?',       where: 'api.stripe.com' },
  { name: 'Accounts',       key: 'Xero up?',         where: 'api.xero.com' },
].map(s => s.key
  ? { ...s, ...check(s.key) }
  : { ...s, state: 'green', note: null });   // this page rendered, so n8n is up

// Anything we failed to ask, gathered up so it can be shown rather than
// shrugged off. A stale or absent host snapshot belongs in the same list.
const blind = services.filter(s => s.state === 'grey')
  .map(s => ({ what: s.name, why: 'the check did not run' }));
if (!hasVitals) blind.push({ what: 'The server', why: 'no snapshot to read' });
units.filter(u => u.state === 'grey')
     .forEach(u => blind.push({ what: u.name, why: 'not installed on the server' }));

const deployRun = (safe('Last deploy', ['body','workflow_runs'], []) || [])[0]
               || (safe('Last deploy', ['workflow_runs'], []) || [])[0];
const deployState = !deployRun ? 'grey'
  : deployRun.status !== 'completed' ? 'amber'
  : deployRun.conclusion === 'success' ? 'green' : 'red';

const overall = worst(
  ...services.map(s => s.state === 'grey' ? 'amber' : s.state),
  ...disks.map(d => d.state), memState, swapState,
  ...certs.map(c => c.state), ...backups.map(b => b.state),
  ...containers.map(c => c.state), updState, vitalsState,
  ...units.map(u => u.state === 'grey' ? 'amber' : u.state),
  deployState === 'grey' ? 'green' : deployState,
);

// --- drawing ---------------------------------------------------------------
const COLOUR = { green:'#0b6e4f', amber:'#b8860b', red:'#990000', grey:'#5a6068' };
const fill = (s) => COLOUR[s] || COLOUR.grey;
const dot = (s) => `<span class="dot" style="background:${fill(s)}"></span>`;

// Every box is a link to the thing it represents. Webmin stays in this tab
// set; the rest open in their own tab, because they are other applications.
const box = (x, y, w, label, sub, state, href) => {
  const body = `
    <rect x="${x}" y="${y}" width="${w}" height="46" rx="7"
          fill="#fff" stroke="${fill(state)}" stroke-width="2.5"/>
    <rect x="${x}" y="${y}" width="5" height="46" rx="2" fill="${fill(state)}"/>
    <text x="${x + 14}" y="${y + 20}" font-size="13" font-weight="600" fill="#222">${esc(label)}</text>
    <text x="${x + 14}" y="${y + 36}" font-size="10.5" fill="#5a6068">${esc(sub)}</text>`;
  if (!href) return `<g>${body}</g>`;
  const blank = href.startsWith('/') ? '' : ' target="_blank" rel="noopener"';
  return `<a href="${esc(href)}"${blank}><g>${body}</g></a>`;
};

// A wire, with the port it runs over written at its midpoint. Almost
// everything here is HTTPS on 443 — the honest and slightly boring truth —
// but writing it on the wire beats making anyone guess.
const wire = (x1, y1, x2, y2, port) =>
  `<path d="M${x1} ${y1} C${(x1+x2)/2} ${y1}, ${(x1+x2)/2} ${y2}, ${x2} ${y2}"
         fill="none" stroke="#c9ced4" stroke-width="2"/>` +
  (port ? `<text x="${(x1+x2)/2}" y="${(y1+y2)/2 - 4}" font-size="8.5"
         text-anchor="middle" fill="#8a9098">${esc(port)}</text>` : '');

const st = (n) => (services.find(s => s.name === n) || {}).state || 'grey';
const unitState = (n) => (units.find(u => u.name === n) || {}).state || 'grey';
const hostState = worst(...disks.map(d => d.state), memState, swapState, vitalsState);

// What runs on your VPS is drawn inside it, because "the VPS is unwell" and
// "Xero is unwell" call for completely different reactions. Everything outside
// the frame is somebody else's machine.
const frame = (x, y, w, h, label, sub, state) => `
  <g>
    <rect x="${x}" y="${y}" width="${w}" height="${h}" rx="12"
          fill="${fill(state)}0d" stroke="${fill(state)}" stroke-width="2.5"
          stroke-dasharray="7 4"/>
    <text x="${x + 16}" y="${y + 24}" font-size="13" font-weight="600"
          fill="${fill(state)}">${esc(label)}</text>
    <text x="${x + 16}" y="${y + 40}" font-size="10.5" fill="#5a6068">${esc(sub)}</text>
  </g>`;

const diagram = `
<svg viewBox="0 40 880 380" class="diagram" role="img"
     aria-label="Component diagram: what runs on your server, what does not,
                 and a status colour on each part">
  ${wire(140, 173, 190, 93, '443')}
  ${wire(140, 173, 190, 173, '443')}
  ${wire(140, 173, 420, 273, 'wss 443')}
  ${wire(340, 93, 420, 133, '443')}
  ${wire(340, 173, 420, 133, 'webhook 443')}
  ${wire(630, 133, 700, 133, '443')}
  ${wire(630, 133, 700, 203, '443')}
  ${wire(630, 133, 700, 273, '443')}
  <path d="M525 156 L525 190" stroke="#c9ced4" stroke-width="2" fill="none"/>
  <text x="532" y="177" font-size="8.5" fill="#8a9098">443</text>

  ${frame(400, 50, 250, 360, 'Your VPS', v.host ? esc(v.host) : 'the server', hostState)}

  ${box(10, 150, 130, 'Customer', 'phone or laptop', 'green')}
  ${box(190, 70, 150, 'Website', 'Netlify', st('Website'), 'https://itsurgery.me')}
  ${box(190, 150, 150, 'Bookings', 'Cal.com', st('Bookings'), 'https://cal.com/it-surgery')}

  ${box(420, 110, 210, 'n8n', 'the automation', 'green', 'https://n8n.itsurgery.me')}
  ${box(420, 190, 210, 'CRM', 'EspoCRM', st('CRM'), 'https://crm.itsurgery.me')}
  ${box(420, 250, 210, 'Remote help', 'MeshCentral', st('Remote help'), 'https://help.itsurgery.me')}

  <!-- No wire: Webmin is not in the customer's path. It administers the
       machine it is drawn inside, which is what the enclosure says. -->
  ${box(420, 320, 210, 'Webmin', 'administers this server', unitState('webmin'), '/webmin-frame')}

  ${box(700, 110, 160, 'Accounts', 'Xero', st('Accounts'), 'https://go.xero.com')}
  ${box(700, 180, 160, 'Payments', 'Stripe', st('Payments'), 'https://dashboard.stripe.com')}
  ${box(700, 250, 160, 'Email', 'Microsoft 365', 'green', 'https://outlook.office.com')}
</svg>`;

const rows = (items) => items.length ? items.join('')
  : '<tr><td class="quiet">Nothing reported.</td></tr>';

const gb = (n) => (n / 1073741824).toFixed(1) + ' GB';
const hrs = (h) => h < 0 ? 'never' : h < 1 ? 'under an hour ago'
  : h < 48 ? h + ' hours ago' : Math.round(h / 24) + ' days ago';

const html = `<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="robots" content="noindex">
<meta http-equiv="refresh" content="120">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Poppins:wght@600&display=swap" rel="stylesheet">
<title>IT Surgery — Monitoring</title>
<style>
 :root{--brand:#990000;--ink:#333;--strong:#222;--quiet:#5a6068;--line:#dcdfe3;--bg:#f4f5f7}
 *{box-sizing:border-box}
 body{margin:0;background:var(--bg);color:var(--ink);
   font:14px/1.45 -apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif}
 header{background:#fff;border-bottom:3px solid var(--brand);padding:.85rem 1.25rem;
   display:flex;align-items:center;gap:.9rem;flex-wrap:wrap}
 header img{height:34px}
 .tabs{display:flex;gap:1.1rem;align-items:center}
 .tabs a{color:var(--brand);font-weight:600;text-decoration:none;font-size:.9rem;padding-bottom:.2rem}
 .tabs a.on{color:var(--strong);border-bottom:2px solid var(--brand)}
 header .when{margin-left:auto;color:var(--quiet);font-size:.85rem}
 main{padding:1rem 1.25rem;max-width:1780px;margin:0 auto}
 @media(min-width:1100px){body{zoom:.75}main{max-width:2400px}}
 h2{font-family:Poppins,sans-serif;font-weight:600;color:var(--strong);margin:0 0 .75rem;font-size:.95rem}
 .card{background:#fff;border:1px solid var(--line);border-radius:10px;padding:1rem;margin-bottom:1rem}
 .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(270px,1fr));gap:1rem}
 .banner{border-radius:10px;padding:1rem 1.15rem;margin-bottom:1rem;color:#fff}
 .banner strong{font-family:Poppins,sans-serif;font-size:1.05rem;display:block}
 .banner span{opacity:.9;font-size:.85rem}
 table{width:100%;border-collapse:collapse}
 td{padding:.45rem 0;border-bottom:1px solid var(--line);font-size:.9rem}
 tr:last-child td{border-bottom:0}
 td.r{text-align:right;white-space:nowrap;color:var(--quiet)}
 .dot{display:inline-block;width:.62rem;height:.62rem;border-radius:50%;margin-right:.5rem}
 .quiet{color:var(--quiet)}
 .bad{color:var(--brand);font-weight:600}
 .diagram{width:100%;height:auto;display:block}
 .diagram a{cursor:pointer}
 .diagram a:hover rect:first-of-type{fill:#f6f7f8}
 .row{display:flex;gap:1rem;align-items:stretch;flex-wrap:wrap;margin-bottom:1rem}
 .row .card.diag{flex:1 1 560px;margin-bottom:0}
 .row .side{flex:1 1 300px;display:flex;flex-direction:column;gap:1rem}
 .row .side .card{margin-bottom:0}
 .stale{background:#fff4d6;border:1px solid #e0c471;border-radius:8px;padding:.7rem .9rem;
   font-size:.85rem;margin-bottom:1rem}
</style></head><body>
<header>
  <img src="https://itsurgery.me/assets/logo.png" alt="IT Surgery">
  <nav class="tabs"><a href="/">Dashboard</a><a class="on" href="/monitoring">Monitoring</a><a href="/webmin-frame">Webmin</a></nav>
  <span class="when">Checked ${esc(new Date().toLocaleString('en-GB',{timeZone:'Europe/London',
    weekday:'short',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}))}</span>
</header>
<main>
  <div class="banner" style="background:${fill(overall)}">
    <strong>${overall === 'green' ? 'Everything is healthy'
            : overall === 'amber' ? 'Something needs attention this week'
            : 'Something needs attention now'}</strong>
    <span>${services.filter(s=>s.state==='green').length} of ${services.length} services responding${
      hasVitals ? ` · host snapshot ${ageMin} min old` : ' · no host snapshot'}${
      blind.length ? ` · ${blind.length} blind spot${blind.length === 1 ? '' : 's'}` : ''}</span>
  </div>

  ${vitalsState !== 'green' ? `<div class="stale"><strong>The host snapshot is ${
     hasVitals ? ageMin + ' minutes old' : 'missing'}.</strong>
     It is rewritten every minute, so this means the timer has stopped.
     Everything below about the server may be out of date. Check
     <code>systemctl status vps-vitals.timer</code> on the VPS.</div>` : ''}

  ${blind.length ? `<div class="stale"><strong>${blind.length} thing${
     blind.length === 1 ? '' : 's'} this page cannot see.</strong>
     ${blind.map(b => esc(b.what) + ' — ' + esc(b.why)).join('; ')}.
     Nothing below covers ${blind.length === 1 ? 'it' : 'them'}, so treat this
     page as incomplete until that is dealt with.</div>` : ''}

  <div class="row">
    <div class="card diag">
      <h2>How it fits together</h2>
      ${diagram}
    </div>
    <div class="side">
      <div class="card"><h2>Services</h2><table>${rows(services.map(s =>
        `<tr><td>${dot(s.state)}${esc(s.name)}</td><td class="r">${
          s.note ? `<span class="bad">${esc(s.note)}</span>` : esc(s.where)}</td></tr>`))}</table></div>
      <div class="card"><h2>Host services</h2><table>${rows(units.map(u =>
        `<tr><td>${dot(u.state)}${esc(u.name)}</td><td class="r">${esc(u.word)}</td></tr>`))}</table></div>
    </div>
  </div>

  <div class="grid">

    <div class="card"><h2>The server</h2><table>
      ${rows(disks.map(d => `<tr><td>${dot(d.state)}Disk ${esc(d.path)}</td>
        <td class="r">${d.pct}% of ${gb(d.size)}</td></tr>`))}
      <tr><td>${dot(memState)}Memory free</td><td class="r">${mem.availableMb || 0} MB of ${mem.totalMb || 0} MB</td></tr>
      <tr><td>${dot(swapState)}Swap used</td><td class="r">${swap.totalMb ? swapPct + '% of ' + swap.totalMb + ' MB' : 'none configured'}</td></tr>
      <tr><td>${dot('green')}Load</td><td class="r">${v.load1 ?? '—'} across ${v.cores ?? '—'} cores</td></tr>
      <tr><td>${dot(updState)}Updates</td><td class="r">${upd.pending ?? 0} pending${
        upd.security ? ', ' + upd.security + ' security' : ''}${upd.rebootRequired ? ', reboot needed' : ''}</td></tr>
    </table></div>

    <div class="card"><h2>Containers</h2><table>${rows(containers.map(c =>
      `<tr><td>${dot(c.state)}${esc(c.name)}</td><td class="r">${esc(c.status)}</td></tr>`))}</table></div>

    <div class="card"><h2>Certificates</h2><table>${rows(certs.map(c =>
      `<tr><td>${dot(c.state)}${esc(c.name)}</td><td class="r">${c.days} days left</td></tr>`))}</table></div>

    <div class="card"><h2>Backups</h2><table>${rows(backups.map(b =>
      `<tr><td>${dot(b.state)}${esc(b.name)}</td><td class="r">${hrs(b.ageHours)}</td></tr>`))}</table></div>

    <div class="card"><h2>Last deploy</h2><table>
      <tr><td>${dot(deployState)}${esc(deployRun ? (deployRun.display_title || '').slice(0,44) : 'No runs found')}</td>
      <td class="r">${deployRun ? esc(deployRun.status === 'completed' ? deployRun.conclusion : deployRun.status) : ''}</td></tr>
    </table></div>
  </div>

  <p class="quiet" style="font-size:.8rem">
    Green means fine. Amber means deal with it this week. Red means now.
    Disks turn amber at 80% and red at 90%; certificates amber at 21 days and
    red at 7; backups amber after 36 hours and red after 72. The page refreshes
    itself every two minutes and the server rewrites its snapshot every minute.
    Certificates, backups and update counts are cached for fifteen minutes —
    they change in days, not seconds.
  </p>
</main></body></html>`;

// The same verdict the page just rendered, in a shape something else can
// diff. Written here and only here, so the watchdog can never drift out of
// step with what the page says.
const state = {
  generated: new Date().toISOString(),
  overall,
  parts: []
    .concat(services.map(s => ({ what: s.name, state: s.state, detail: s.note || s.where })))
    .concat(units.map(u => ({ what: 'service ' + u.name, state: u.state, detail: u.word })))
    .concat(containers.map(c => ({ what: 'container ' + c.name, state: c.state, detail: c.status })))
    .concat(disks.map(d => ({ what: 'disk ' + d.path, state: d.state, detail: d.pct + '% full' })))
    .concat(certs.map(c => ({ what: 'certificate ' + c.name, state: c.state, detail: c.days + ' days left' })))
    .concat(backups.map(b => ({ what: 'backup ' + b.name, state: b.state, detail: hrs(b.ageHours) })))
    .concat([
      { what: 'memory',   state: memState,    detail: (mem.availableMb || 0) + ' MB free' },
      { what: 'swap',     state: swapState,   detail: swapPct + '% used' },
      { what: 'updates',  state: updState,    detail: (upd.pending ?? 0) + ' pending' },
      { what: 'snapshot', state: vitalsState, detail: hasVitals ? ageMin + ' min old' : 'missing' },
      { what: 'deploy',   state: deployState === 'grey' ? 'green' : deployState,
        detail: deployRun ? (deployRun.conclusion || deployRun.status) : 'no runs' },
    ]),
};

return [{ json: { html, state } }];
